import { Dimensions, StyleSheet } from 'react-native';

const { width } = Dimensions.get('window');

export const styles = StyleSheet.create({
    container: {
        flex: 1,
        backgroundColor: '#F5F6F7',
    },
    headerContainer: {
        backgroundColor: '#fff',
        paddingBottom: 5,
        borderBottomWidth: StyleSheet.hairlineWidth,
        borderBottomColor: '#EEE',
        // zIndex 在 JSX 中动态设置了
    },
    // --- 搜索框相关 ---
    searchBarContainer: {
        flexDirection: 'row',
        alignItems: 'center',
        paddingHorizontal: 12,
        paddingVertical: 10,
        backgroundColor: '#fff',
    },
    backButton: { width: 30, justifyContent: 'center' },
    backIcon: { fontSize: 22, color: '#333' },
    searchMainContent: {
        flex: 1,
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#F2F4F7',
        borderRadius: 25,
        paddingHorizontal: 12,
        paddingVertical: 6,
    },
    cityText: { fontSize: 15, fontWeight: 'bold', color: '#333', marginRight: 8 },
    dateVerticalContainer: { marginRight: 6, justifyContent: 'center' },
    dateRow: { flexDirection: 'row', alignItems: 'center' },
    dateLabel: { fontSize: 9, color: '#999', marginRight: 2 },
    dateValue: { fontSize: 10, color: '#3388FF', fontWeight: '500' },
    nightCountText: { fontSize: 10, color: '#666', marginRight: 8 },
    verticalDivider: { width: 1, height: 14, backgroundColor: '#DDD', marginRight: 8 },
    keywordContainer: { flex: 1, flexDirection: 'row', alignItems: 'center' },
    searchIcon: { fontSize: 14, marginRight: 6 },
    keywordPlaceholder: { fontSize: 13, color: '#333', flex: 1, padding: 0 },

    // --- 筛选栏相关 ---
    filterRow: {
        flexDirection: 'row',
        justifyContent: 'space-around',
        paddingVertical: 12,
        backgroundColor: '#fff',
        borderTopWidth: 1,
        borderTopColor: '#f5f5f5'
    },
    filterItem: {
        flexDirection: 'row',
        alignItems: 'center',
        paddingHorizontal: 4,
        paddingVertical: 4,
    },
    filterText: {
        fontSize: 13,
        color: '#666',
    },
    activeFilterText: {
        color: '#0086F6', // 携程蓝
        fontWeight: 'bold',
    },
    arrowIcon: {
        fontSize: 10,
        marginLeft: 4,
        color: '#999',
    },
    activeArrowIcon: {
        color: '#0086F6',
    },

    // --- 下拉菜单核心样式 (新增) ---
    dropdownContainer: {
        position: 'absolute',
        top: '100%', // 位于 header 底部
        left: 0,
        right: 0,
        height: height, // 撑满屏幕高度以便显示蒙层
        zIndex: 100,
    },
    mask: {
        position: 'absolute',
        top: 0,
        bottom: 0,
        left: 0,
        right: 0,
        backgroundColor: 'rgba(0,0,0,0.5)', // 半透明黑色
    },
    dropdownContent: {
        backgroundColor: '#fff',
        width: '100%',
        maxHeight: 400, // 限制最大高度
        borderBottomLeftRadius: 12,
        borderBottomRightRadius: 12,
    },
    dropdownList: {
        paddingVertical: 5,
    },
    dropdownItem: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        paddingVertical: 14,
        paddingHorizontal: 20,
        borderBottomWidth: StyleSheet.hairlineWidth,
        borderBottomColor: '#f0f0f0',
    },
    dropdownItemText: {
        fontSize: 14,
        color: '#333',
    },
    activeDropdownItemText: {
        color: '#0086F6',
        fontWeight: 'bold',
    },
    checkIcon: {
        color: '#0086F6',
        fontSize: 16,
    },

    // --- 列表样式 ---
    hotelItem: {
        flexDirection: 'row',
        backgroundColor: '#fff',
        marginHorizontal: 12,
        marginTop: 12,
        borderRadius: 12,
        padding: 12,
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.05,
        shadowRadius: 5,
        elevation: 2,
    },
    hotelImage: { width: 100, height: 130, borderRadius: 8 },
    infoArea: { flex: 1, marginLeft: 12, justifyContent: 'space-between' },
    hotelName: { fontSize: 16, fontWeight: 'bold', color: '#333' },
    scoreRow: { flexDirection: 'row', alignItems: 'center', marginTop: 4 },
    scoreText: { fontSize: 14, color: '#007AFF', fontWeight: 'bold' },
    commentText: { fontSize: 12, color: '#666', marginLeft: 8 },
    addressText: { fontSize: 12, color: '#999', marginTop: 4 },
    tagRow: { flexDirection: 'row', flexWrap: 'wrap', marginTop: 8 },
    hotelTag: { backgroundColor: '#E8F3FF', paddingHorizontal: 6, paddingVertical: 2, borderRadius: 4, marginRight: 6, marginBottom: 4 },
    hotelTagText: { fontSize: 10, color: '#007AFF' },
    priceContainer: { flexDirection: 'row', alignItems: 'baseline', justifyContent: 'flex-end' },
    priceSymbol: { fontSize: 12, color: '#FF5A5F', fontWeight: 'bold' },
    priceText: { fontSize: 20, color: '#FF5A5F', fontWeight: 'bold' },
    priceUnit: { fontSize: 11, color: '#999', marginLeft: 2 },
    footerLoading: { paddingVertical: 20, alignItems: 'center' },
    
  
    
   
   
  
   
   
    
});
